+  setUp(() {
+    sandbox = io.Directory.systemTemp.createTempSync('fah_1713_ssh');
+    rec = _Recorder();
+    addTearDown(() => sandbox.deleteSync(recursive: true));
+  });
+
+  WasmSshCommands commands() => WasmSshCommands(
