+      expect(await builtins.localKind('/f.txt'), SandboxSshEntryKind.file);
+      expect(await builtins.localKind('/d'), SandboxSshEntryKind.directory);
+      expect(await builtins.localKind('/missing'), isNull);
+    });
+
